import React, { useState, useContext } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { AuthContext } from '../../context/AuthContext';
import { FiEye, FiEyeOff } from 'react-icons/fi';
import SkillBridgeLogo from '../../assets/logo/SkillBridgeLogo';

const COUNTRIES = [
  'India','United States','United Kingdom','Canada','Australia','Germany','France',
  'Singapore','UAE','Netherlands','Sweden','Norway','Denmark','Finland','New Zealand',
  'South Africa','Brazil','Mexico','Japan','South Korea','Other'
];

const Register = () => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: '',
    country: 'India',
    userType: '',
    emailConsent: true,
    termsAccepted: false,
  });
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const { register } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData({ ...formData, [name]: type === 'checkbox' ? checked : value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.termsAccepted) {
      setError('Please accept the Terms of Service to continue.');
      return;
    }
    setError('');
    try {
      const fullName = `${formData.firstName.trim()} ${formData.lastName.trim()}`.trim();
      await register(fullName, formData.email, formData.password, formData.userType);
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.msg || 'Registration failed');
    }
  };

  // Step 1: Role selection (Upwork style)
  if (step === 1) {
    return (
      <div className="min-h-screen bg-white">
        {/* Top bar with logo only */}
        <div style={{ borderBottom: '1px solid #e0e0e0' }}>
          <div style={{ padding: '20px 24px' }}>
            <Link to="/">
              <SkillBridgeLogo width={130} height={20} />
            </Link>
          </div>
        </div>

        {/* Role selection content */}
        <div style={{ maxWidth: '680px', margin: '0 auto', padding: '64px 24px', textAlign: 'center' }}>
          <h1 style={{
            fontFamily: "'Neue Montreal', 'Plus Jakarta Sans', sans-serif",
            fontSize: '32px',
            fontWeight: 500,
            color: '#181818',
            marginBottom: '48px',
            lineHeight: 1.25
          }}>
            Join as a client or student
          </h1>

          {/* Cards */}
          <div style={{ display: 'flex', gap: '16px', justifyContent: 'center', marginBottom: '32px' }}>
            {/* Client Card */}
            <button
              type="button"
              onClick={() => setFormData({ ...formData, userType: 'client' })}
              style={{
                width: '240px',
                minHeight: '140px',
                padding: '24px',
                border: formData.userType === 'client' ? '2px solid #181818' : '1px solid #beccbe',
                borderRadius: '8px',
                background: '#fff',
                cursor: 'pointer',
                textAlign: 'left',
                position: 'relative',
                transition: 'border-color 0.15s ease, box-shadow 0.15s ease',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'space-between'
              }}
              onMouseEnter={(e) => {
                if (formData.userType !== 'client') {
                  e.currentTarget.style.borderColor = '#181818';
                }
              }}
              onMouseLeave={(e) => {
                if (formData.userType !== 'client') {
                  e.currentTarget.style.borderColor = '#beccbe';
                }
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                {/* Client icon - user-add */}
                <svg width="32" height="32" viewBox="0 0 24 24" fill="#181818" xmlns="http://www.w3.org/2000/svg">
                  <path d="M23,11H21V9a1,1,0,0,0-2,0v2H17a1,1,0,0,0,0,2h2v2a1,1,0,0,0,2,0V13h2a1,1,0,0,0,0-2Z"/><path d="M9,12A6,6,0,1,0,3,6,6.006,6.006,0,0,0,9,12ZM9,2A4,4,0,1,1,5,6,4,4,0,0,1,9,2Z"/><path d="M9,14a9.01,9.01,0,0,0-9,9,1,1,0,0,0,2,0,7,7,0,0,1,14,0,1,1,0,0,0,2,0A9.01,9.01,0,0,0,9,14Z"/>
                </svg>
                {/* Radio circle */}
                <div style={{
                  width: '24px',
                  height: '24px',
                  borderRadius: '50%',
                  border: formData.userType === 'client' ? '7px solid #181818' : '2px solid #beccbe',
                  transition: 'border 0.15s ease',
                  flexShrink: 0
                }} />
              </div>
              <p style={{
                fontFamily: "'Plus Jakarta Sans', sans-serif",
                fontSize: '16px',
                fontWeight: 500,
                color: '#181818',
                lineHeight: 1.4,
                marginTop: '16px'
              }}>
                I'm a client, hiring for<br />a project
              </p>
            </button>

            {/* Student Card */}
            <button
              type="button"
              onClick={() => setFormData({ ...formData, userType: 'student' })}
              style={{
                width: '240px',
                minHeight: '140px',
                padding: '24px',
                border: formData.userType === 'student' ? '2px solid #181818' : '1px solid #beccbe',
                borderRadius: '8px',
                background: '#fff',
                cursor: 'pointer',
                textAlign: 'left',
                position: 'relative',
                transition: 'border-color 0.15s ease, box-shadow 0.15s ease',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'space-between'
              }}
              onMouseEnter={(e) => {
                if (formData.userType !== 'student') {
                  e.currentTarget.style.borderColor = '#181818';
                }
              }}
              onMouseLeave={(e) => {
                if (formData.userType !== 'student') {
                  e.currentTarget.style.borderColor = '#beccbe';
                }
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                {/* Student icon - member-search */}
                <svg width="32" height="32" viewBox="0 0 24 24" fill="#181818" xmlns="http://www.w3.org/2000/svg">
                  <path d="M23.707,22.293l-3.54-3.54c.524-.791,.833-1.736,.833-2.753,0-2.757-2.243-5-5-5s-5,2.243-5,5,2.243,5,5,5c1.017,0,1.962-.309,2.753-.833l3.54,3.54c.195,.195,.451,.293,.707,.293s.512-.098,.707-.293c.391-.391,.391-1.023,0-1.414Zm-10.707-6.293c0-1.654,1.346-3,3-3s3,1.346,3,3-1.346,3-3,3-3-1.346-3-3Zm2-10c0-3.309-2.691-6-6-6S3,2.691,3,6s2.691,6,6,6,6-2.691,6-6Zm-6,4c-2.206,0-4-1.794-4-4s1.794-4,4-4,4,1.794,4,4-1.794,4-4,4Zm-.008,4.938c.068,.548-.32,1.047-.869,1.116-3.491,.436-6.124,3.421-6.124,6.946,0,.552-.448,1-1,1s-1-.448-1-1c0-4.531,3.386-8.37,7.876-8.93,.542-.069,1.047,.32,1.116,.869Z"/>
                </svg>
                {/* Radio circle */}
                <div style={{
                  width: '24px',
                  height: '24px',
                  borderRadius: '50%',
                  border: formData.userType === 'student' ? '7px solid #181818' : '2px solid #beccbe',
                  transition: 'border 0.15s ease',
                  flexShrink: 0
                }} />
              </div>
              <p style={{
                fontFamily: "'Plus Jakarta Sans', sans-serif",
                fontSize: '16px',
                fontWeight: 500,
                color: '#181818',
                lineHeight: 1.4,
                marginTop: '16px'
              }}>
                I'm a student,<br />looking for work
              </p>
            </button>
          </div>

          {/* Create Account Button */}
          <button
            type="button"
            disabled={!formData.userType}
            onClick={() => setStep(2)}
            style={{
              fontFamily: "'Plus Jakarta Sans', sans-serif",
              fontSize: '16px',
              fontWeight: 500,
              padding: '12px 32px',
              borderRadius: '10rem',
              border: 'none',
              color: '#fff',
              background: formData.userType ? '#14A800' : '#d5e0d5',
              cursor: formData.userType ? 'pointer' : 'default',
              transition: 'background 0.15s ease',
              marginBottom: '24px'
            }}
            onMouseEnter={(e) => {
              if (formData.userType) e.currentTarget.style.background = '#1dbf00';
            }}
            onMouseLeave={(e) => {
              if (formData.userType) e.currentTarget.style.background = '#14A800';
            }}
          >
            {formData.userType === 'client' ? 'Join as a Client' : formData.userType === 'student' ? 'Apply as a Student' : 'Create Account'}
          </button>

          {/* Already have account */}
          <p style={{
            fontFamily: "'Plus Jakarta Sans', sans-serif",
            fontSize: '14px',
            color: '#181818'
          }}>
            Already have an account?{' '}
            <Link to="/login" style={{
              color: '#14A800',
              textDecoration: 'underline',
              fontWeight: 500
            }}>
              Log In
            </Link>
          </p>
        </div>
      </div>
    );
  }

  // Step 2: Registration form
  return (
    <div className="min-h-screen bg-white">
      {/* Top bar with logo */}
      <div style={{ borderBottom: '1px solid #e0e0e0' }}>
        <div style={{ padding: '20px 24px' }}>
          <Link to="/">
            <SkillBridgeLogo width={130} height={20} />
          </Link>
        </div>
      </div>

      <div style={{ maxWidth: '500px', margin: '0 auto', padding: '48px 24px' }}>
        <div style={{ textAlign: 'center', marginBottom: '32px' }}>
          <h2 style={{
            fontFamily: "'Neue Montreal', 'Plus Jakarta Sans', sans-serif",
            fontSize: '28px',
            fontWeight: 500,
            color: '#181818',
            marginBottom: '8px'
          }}>
            Sign up to {formData.userType === 'client' ? 'hire talent' : 'find work you love'}
          </h2>
          <button
            type="button"
            onClick={() => setStep(1)}
            style={{
              fontFamily: "'Plus Jakarta Sans', sans-serif",
              fontSize: '14px',
              color: '#14A800',
              textDecoration: 'underline',
              background: 'none',
              border: 'none',
              cursor: 'pointer',
              fontWeight: 500
            }}
          >
            ← Back to role selection
          </button>
        </div>

        {error && (
          <div style={{
            background: '#fef2f2',
            border: '1px solid #fecaca',
            color: '#dc2626',
            padding: '12px 16px',
            borderRadius: '8px',
            marginBottom: '24px',
            fontSize: '14px',
            fontFamily: "'Plus Jakarta Sans', sans-serif"
          }}>
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '20px' }}>
            <label style={{
              display: 'block',
              fontFamily: "'Plus Jakarta Sans', sans-serif",
              fontSize: '14px',
              fontWeight: 500,
              color: '#181818',
              marginBottom: '8px'
            }}>Full Name</label>
            <div style={{ position: 'relative' }}>
              <FiUser style={{ position: 'absolute', left: '14px', top: '14px', color: '#9aaa97' }} />
              <input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleChange}
                placeholder="John Doe"
                required
                style={{
                  width: '100%',
                  padding: '12px 14px 12px 40px',
                  border: '1px solid #beccbe',
                  borderRadius: '8px',
                  fontSize: '16px',
                  fontFamily: "'Plus Jakarta Sans', sans-serif",
                  color: '#181818',
                  outline: 'none',
                  transition: 'border-color 0.15s ease',
                  boxSizing: 'border-box'
                }}
                onFocus={(e) => e.target.style.borderColor = '#181818'}
                onBlur={(e) => e.target.style.borderColor = '#beccbe'}
              />
            </div>
          </div>

          <div style={{ marginBottom: '20px' }}>
            <label style={{
              display: 'block',
              fontFamily: "'Plus Jakarta Sans', sans-serif",
              fontSize: '14px',
              fontWeight: 500,
              color: '#181818',
              marginBottom: '8px'
            }}>Email</label>
            <div style={{ position: 'relative' }}>
              <FiMail style={{ position: 'absolute', left: '14px', top: '14px', color: '#9aaa97' }} />
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                placeholder="your@email.com"
                required
                style={{
                  width: '100%',
                  padding: '12px 14px 12px 40px',
                  border: '1px solid #beccbe',
                  borderRadius: '8px',
                  fontSize: '16px',
                  fontFamily: "'Plus Jakarta Sans', sans-serif",
                  color: '#181818',
                  outline: 'none',
                  transition: 'border-color 0.15s ease',
                  boxSizing: 'border-box'
                }}
                onFocus={(e) => e.target.style.borderColor = '#181818'}
                onBlur={(e) => e.target.style.borderColor = '#beccbe'}
              />
            </div>
          </div>

          <div style={{ marginBottom: '28px' }}>
            <label style={{
              display: 'block',
              fontFamily: "'Plus Jakarta Sans', sans-serif",
              fontSize: '14px',
              fontWeight: 500,
              color: '#181818',
              marginBottom: '8px'
            }}>Password</label>
            <div style={{ position: 'relative' }}>
              <FiLock style={{ position: 'absolute', left: '14px', top: '14px', color: '#9aaa97' }} />
              <input
                type="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                placeholder="Minimum 6 characters"
                required
                minLength="6"
                style={{
                  width: '100%',
                  padding: '12px 14px 12px 40px',
                  border: '1px solid #beccbe',
                  borderRadius: '8px',
                  fontSize: '16px',
                  fontFamily: "'Plus Jakarta Sans', sans-serif",
                  color: '#181818',
                  outline: 'none',
                  transition: 'border-color 0.15s ease',
                  boxSizing: 'border-box'
                }}
                onFocus={(e) => e.target.style.borderColor = '#181818'}
                onBlur={(e) => e.target.style.borderColor = '#beccbe'}
              />
            </div>
          </div>

          <button
            type="submit"
            style={{
              width: '100%',
              fontFamily: "'Plus Jakarta Sans', sans-serif",
              fontSize: '16px',
              fontWeight: 500,
              padding: '12px',
              borderRadius: '10rem',
              border: 'none',
              color: '#fff',
              background: '#14A800',
              cursor: 'pointer',
              transition: 'background 0.15s ease',
              marginBottom: '24px'
            }}
            onMouseEnter={(e) => e.currentTarget.style.background = '#1dbf00'}
            onMouseLeave={(e) => e.currentTarget.style.background = '#14A800'}
          >
            Create Account
          </button>
        </form>

        <p style={{
          textAlign: 'center',
          fontFamily: "'Plus Jakarta Sans', sans-serif",
          fontSize: '14px',
          color: '#181818'
        }}>
          Already have an account?{' '}
          <Link to="/login" style={{
            color: '#14A800',
            textDecoration: 'underline',
            fontWeight: 500
          }}>
            Log In
          </Link>
        </p>
      </div>
    </div>
  );
};

export default Register;
